\begin{tikzpicture}[scale=0.72]
  \draw[->] (0,0) -- (0,4.2) node[above,font=\small] {$^\circ$C};
  \draw[->] (0,0) -- (7.2,0);
  \foreach \y/\t in {0/0,1/5,2/10,3/15,4/20}
    \draw (-0.1,\y) -- (0.1,\y) node[left,font=\scriptsize] {\t};
  \foreach \x/\m in {1/4,2/5,3/6,4/7,5/8,6/9}
    \draw (\x,-0.1) -- (\x,0.1) node[below,font=\scriptsize] {\m 月};
  \draw[thick,band] (1,2.0) -- (2,2.8) -- (3,3.4) -- (4,3.9) -- (5,3.7) -- (6,3.0);
  \foreach \p in {(1,2.0),(2,2.8),(3,3.4),(4,3.9),(5,3.7),(6,3.0)} \fill \p circle (1.5pt);
\end{tikzpicture}
\end{center}
